CREATE DATABASE IF NOT EXISTS noframe CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE noframe;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS user_profiles; DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS orders; DROP TABLE IF EXISTS reviews; DROP TABLE IF EXISTS products; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS users;
CREATE TABLE users (id VARCHAR(50) PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) DEFAULT 'customer',promo TINYINT(1) DEFAULT 0,discount_pin VARCHAR(20) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
-- Existing databases: run the line below once instead of reloading the schema
-- ALTER TABLE users ADD COLUMN discount_pin VARCHAR(20) NULL;
CREATE TABLE user_profiles (user_id VARCHAR(50) PRIMARY KEY,phone VARCHAR(50),shipping_address TEXT,billing_address TEXT,avatar VARCHAR(255) DEFAULT '/assets/u1.svg',account_status VARCHAR(50) DEFAULT 'Active Member',CONSTRAINT fk_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories (id VARCHAR(80) PRIMARY KEY,name VARCHAR(150) NOT NULL,cover_image TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id VARCHAR(80) PRIMARY KEY,title VARCHAR(255) NOT NULL,category_id VARCHAR(80) NOT NULL,category_name VARCHAR(150),price DECIMAL(12,2) NOT NULL DEFAULT 0,discount_price DECIMAL(12,2) NULL,stock INT DEFAULT 0,colors TEXT,sizes TEXT,images TEXT,rating DECIMAL(3,2) DEFAULT 4.5,reviews_count INT DEFAULT 0,tags TEXT,description TEXT,price_updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE orders (id VARCHAR(80) PRIMARY KEY,user_id VARCHAR(50) NULL,items TEXT,subtotal DECIMAL(12,2),delivery DECIMAL(12,2),total DECIMAL(12,2),status VARCHAR(50) DEFAULT 'Pending',shipping TEXT,created_at BIGINT,CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id VARCHAR(80),product_id VARCHAR(80),title VARCHAR(255),qty INT,size VARCHAR(80),color VARCHAR(80),price DECIMAL(12,2),CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id VARCHAR(80),user_id VARCHAR(50),user_name VARCHAR(150),rating INT,comment TEXT,approved TINYINT(1) DEFAULT 1,created_at BIGINT,CONSTRAINT fk_review_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
